'use client';

/**
 * SpacecraftViewer — real GLB spacecraft models with an AR launch path.
 *
 * The models in `/public/models` are generated by `scripts/build-3d-models.mjs`
 * (GLTFExporter + USDZExporter), so every craft is a genuine 3D asset rather
 * than a primitive assembled inside the render tree. The same files back:
 *  - the interactive WebGL view here (drei `useGLTF`, OrbitControls)
 *  - Android Scene Viewer AR via an https `file` intent
 *  - iOS Quick Look AR via the .usdz companion and `rel="ar"`
 */

