// Warm the model cache after the viewer mounts so switching craft is instant;
// total payload is under 300 KB of GLB and no network work happens at import.
function usePreloadSpacecraft() {
  useEffect(() => {
    CATALOG.forEach(({ glb }) => useGLTF.preload(glb));
  }, []);
}

function SpacecraftModel({ url, spinning }: { url: string; spinning: boolean }) {
  const { scene } = useGLTF(url);
  const root = useRef<THREE.Group>(null);

  // The GLTF cache shares scene objects; clone so auto-rotation and remounts
  // never mutate the cached asset. Materials stay shared (read-only here).
  const model = useMemo(() => scene.clone(true), [scene]);

  useFrame((_, delta) => {
    if (spinning && root.current) root.current.rotation.y += delta * 0.45;
  });

  return (
    <group ref={root}>
      <primitive object={model} />
    </group>
  );
}

function sceneViewerUrl(glbPath: string): string {
  const origin = typeof window === 'undefined' ? '' : window.location.origin;
  const file = encodeURIComponent(`${origin}${glbPath}`);
  return `https://arvr.google.com/scene-viewer/ar?file=${file}&mode=ar_only&resizable=false`;
}

