export default function SpacecraftViewer({ lang = 'en' }: { lang?: SupportedLanguage }) {
  usePreloadSpacecraft();
  const [selectedId, setSelectedId] = useState(CATALOG[0].id);
  const [spinning, setSpinning] = useState(true);
  const { isOptimizedModeActive } = useDevicePerformance();
  const selected = CATALOG.find((c) => c.id === selectedId) ?? CATALOG[0];

  return (
    <div className="overflow-hidden rounded-3xl border border-cyan-500/30 bg-abyss">
      {/* Header / model picker */}
      <div className="flex flex-col gap-3 border-b border-white/10 p-4 sm:p-5">
        <div className="flex items-center gap-2.5">
          <Satellite className="h-4.5 w-4.5 text-cyan-300" />
          <div>
            <p className="text-sm font-semibold text-ink">{copy.title[lang]}</p>
            <p className="text-[11px] text-ink-3">{copy.subtitle[lang]}</p>
          </div>
        </div>
        <div className="flex flex-wrap gap-1.5" role="tablist" aria-label="Spacecraft models">
          {CATALOG.map((craft) => (
            <button
              key={craft.id}
              type="button"
              role="tab"
              aria-selected={craft.id === selectedId}
              onClick={() => setSelectedId(craft.id)}
              className={`rounded-[10px] border px-3 py-1.5 text-[11.5px] font-semibold transition cursor-pointer ${
                craft.id === selectedId
                  ? 'border-cyan-400/60 bg-cyan-500/20 text-cyan-100'
                  : 'border-white/10 bg-white/[0.03] text-ink-2 hover:border-cyan-400/30 hover:text-ink'
              }`}
            >
              {craft.name[lang]}
            </button>
          ))}
        </div>
      </div>

      {/* 3D viewport */}
      <div className="relative h-[420px] sm:h-[520px]">
        <Canvas
          dpr={[1, isOptimizedModeActive ? 1.25 : 1.75]}
          camera={{ position: [4.2, 1.6, 5.2], fov: 40 }}
          gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
          onCreated={({ gl }) => gl.setClearColor(0x000000, 0)}
        >
          <ambientLight intensity={0.55} />
          <hemisphereLight args={[0xbfe3ff, 0x141a26, 0.5]} />
          <directionalLight position={[5, 6, 4]} intensity={2.1} castShadow />
          <directionalLight position={[-5, -2, -3]} intensity={0.55} color="#8fb8ff" />

          <Suspense
            fallback={
              <Html center>
                <div className="flex items-center gap-2 whitespace-nowrap rounded-full border border-white/10 bg-abyss/90 px-4 py-2 text-[11.5px] text-ink-2">
                  <Loader2 className="h-3.5 w-3.5 animate-spin text-cyan-300" />
                  {copy.loading[lang]}
                </div>
              </Html>
            }
          >
            <SpacecraftModel key={selected.id} url={selected.glb} spinning={spinning} />
            <ContactShadows position={[0, -2.15, 0]} opacity={0.45} scale={9} blur={2.4} far={5} color="#000814" />
          </Suspense>

          <OrbitControls
            enablePan={false}
            enableDamping
            dampingFactor={0.08}
            minDistance={3}
            maxDistance={10}
            maxPolarAngle={Math.PI * 0.85}
          />
        </Canvas>

        {/* Rotation toggle */}
        <button
          type="button"
          onClick={() => setSpinning((v) => !v)}
          className={`absolute right-3 top-3 flex items-center gap-1.5 rounded-[10px] border px-2.5 py-1.5 text-[11px] font-semibold transition cursor-pointer ${
            spinning
              ? 'border-cyan-400/50 bg-cyan-500/20 text-cyan-100'
              : 'border-white/10 bg-abyss/70 text-ink-2 hover:text-ink'
          }`}
        >
          <RotateCw className={`h-3.5 w-3.5 ${spinning ? 'animate-[spin_3s_linear_infinite]' : ''}`} />
          {copy.spin[lang]}
        </button>
      </div>

      {/* Caption + AR actions */}
      <div className="flex flex-col gap-3 border-t border-white/10 p-4 sm:flex-row sm:items-center sm:justify-between sm:p-5">
        <div className="min-w-0">
          <p className="flex items-center gap-2 text-sm font-semibold text-ink">
            <Box className="h-4 w-4 shrink-0 text-cyan-300" />
            {selected.name[lang]}
          </p>
          <p className="mt-1 max-w-xl text-[11.5px] leading-relaxed text-ink-3">{selected.detail[lang]}</p>
        </div>
        <div className="flex shrink-0 flex-wrap gap-2">
          <a
            href={sceneViewerUrl(selected.glb)}
            target="_blank"
            rel="noreferrer noopener"
            className="inline-flex items-center gap-1.5 rounded-[10px] bg-gradient-to-r from-cyan-600 to-blue-600 px-3 py-2 text-[11.5px] font-semibold text-white transition hover:from-cyan-500 hover:to-blue-500"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            {copy.arAndroid[lang]}
          </a>
          {/* iOS Quick Look: Safari intercepts rel="ar" anchors and opens the USDZ. */}
          <a
            href={selected.usdz}
            rel="ar"
            className="inline-flex items-center gap-1.5 rounded-[10px] border border-white/15 bg-white/[0.05] px-3 py-2 text-[11.5px] font-semibold text-ink transition hover:border-cyan-400/40 hover:text-cyan-100"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            {copy.arIos[lang]}
          </a>
        </div>
      </div>
    </div>
  );
}
